export type Ctx = { path: string; body: unknown };
export type Next = () => Promise<void>;
export type Middleware = (ctx: Ctx, next: Next) => Promise<void> | void;

/** A router that is not itself a middleware: `routes()` hands one back. */
export interface Router {
  use(path: string, ...middleware: Middleware[]): this;
  use(...middleware: Middleware[]): this;
  post(path: string, handler: Middleware): this;
  /** A middleware serving this router's routes at its own address. */
  routes(): Middleware;
}

declare function router(): Router;
export default router;
